BEGIN TRANSACTION READ ONLY;
WITH expected AS (SELECT 'public.upsert_workday_record(uuid,uuid,date,uuid,text,timestamptz,timestamptz,integer,integer,integer,integer,integer,text,text,integer,uuid,timestamptz,integer)'::text AS signature), fn AS (SELECT p.* FROM pg_proc p CROSS JOIN expected e WHERE p.oid=to_regprocedure(e.signature)), checks AS (SELECT to_regclass('public.attendance_persist_outbox') IS NOT NULL AS outbox_exists,EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='workday_records' AND column_name='source_observed_at' AND udt_name='timestamptz') AS workday_observed_at_exists,EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='workday_records' AND column_name='source_event_count' AND udt_name='int4') AS workday_count_exists,EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='workday_record_history' AND column_name='source_observed_at' AND udt_name='timestamptz') AS history_observed_at_exists,EXISTS(SELECT 1 FROM fn WHERE NOT has_function_privilege('anon',oid,'EXECUTE') AND NOT has_function_privilege('authenticated',oid,'EXECUTE') AND has_function_privilege('service_role',oid,'EXECUTE')) AS evolution_rpc_service_role_only,NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=to_regprocedure('public.upsert_workday_record(uuid,uuid,date,uuid,text,timestamptz,timestamptz,integer,integer,integer,integer,integer,text,text,integer,uuid)') AND has_function_privilege('service_role',p.oid,'EXECUTE')) AS legacy_rpc_revoked,EXISTS(SELECT 1 FROM fn WHERE lower(pg_get_functiondef(oid)) LIKE '%source_observed_at%' AND lower(pg_get_functiondef(oid)) LIKE '%source_event_count%' AND lower(pg_get_functiondef(oid)) LIKE '%persist_snapshot_conflict%' AND lower(pg_get_functiondef(oid)) NOT LIKE '%public.horarios%') AS monotonic_revision_only_contract,NOT EXISTS(SELECT 1 FROM public.tenant_features WHERE feature_key='WORKDAY_PERSIST_ACTIVE' AND enabled) AS productive_gate_closed), entries AS (SELECT entry.key,entry.value FROM checks CROSS JOIN LATERAL jsonb_each_text(to_jsonb(checks)) entry(key,value)), failed AS (SELECT COALESCE(jsonb_agg(key ORDER BY key) FILTER(WHERE value<>'true'),'[]'::jsonb) value FROM entries) SELECT jsonb_build_object('phase','98_workday_evolution_postcheck','read_only',current_setting('transaction_read_only'),'checks',(SELECT to_jsonb(checks) FROM checks),'failed_checks',(SELECT value FROM failed),'pass',(SELECT value='[]'::jsonb FROM failed)) FROM checks;
ROLLBACK;
